/** 
 * @param {number} target
 * @return {number}
 */
Array.prototype.upperBound = function(target) {
    let l = 0, r = this.length - 1;
    let ans = -1;
    while (l <= r) {
        const mid = (l + r) >> 1;
        if (this[mid] === target) {
            ans = mid;
            l = mid + 1;
        } else if (this[mid] < target) {
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    return ans;
};
